var MoviePerformanceTrackResolver=class{static resolve(type){return{pose:"track_action",action:"track_action",emotion:"track_emotion",gesture:"track_gesture",prop:"track_props"}[type]||"track_effects"}};var MovieClipFactory=class{static clip(clip){return{entityId:null,transform:{x:0,y:0,scale:1,rotation:0,opacity:1,anchor:[.5,.5]},...clip}}static sequence(sequence){return this.clip({id:`composition_${sequence.id}`,trackId:"track_composition",start:sequence.start,duration:sequence.duration,type:"composition",name:sequence.name,payload:{sequenceId:sequence.id,transition:sequence.transition,nested:!0}})}static shot(shot){return this.clip({id:`camera_${shot.id}`,trackId:"track_camera",start:shot.start,duration:shot.duration,type:"camera",name:`${shot.camera.size} ${shot.camera.angle}`,payload:{...shot.camera,sequenceId:shot.sequenceId,transition:shot.transition,continuity:shot.continuity}})}static dialogue(line){return this.clip({id:`dialogue_${line.id}`,trackId:"track_dialogue",entityId:line.speakerId,start:line.start,duration:line.duration,type:"dialogue",name:`${line.speakerName}: ${line.text.slice(0,28)}`,payload:{...line}})}static bubble(line){return this.clip({id:`bubble_${line.id}`,trackId:"track_titles",entityId:line.speakerId,start:line.start,duration:line.duration,type:"bubble",name:`Bubble: ${line.text.slice(0,24)}`,payload:{text:line.text,speakerId:line.speakerId,sequenceId:line.sequenceId,displayMode:line.displayMode}})}static performance(performance){return this.clip({id:performance.id,trackId:MoviePerformanceTrackResolver.resolve(performance.type),entityId:performance.characterId,start:performance.start,duration:performance.duration,type:performance.type,name:performance.name,payload:{...performance.payload,sequenceId:performance.sequenceId}})}static asset(asset){return this.clip({id:asset.id,trackId:asset.trackId,start:asset.start,duration:asset.duration,type:asset.type,name:asset.name,payload:asset.payload})}};var MoviePlanCompiler=class{static compile(plan){return{duration:plan.duration,tracks:this.tracks(),clips:[...plan.sequences.map(sequence=>MovieClipFactory.sequence(sequence)),...plan.shots.map(shot=>MovieClipFactory.shot(shot)),...this.dialogueClips(plan.dialogue),...(plan.performances||[]).map(item=>MovieClipFactory.performance(item)),...(plan.assetUses||[]).map(item=>MovieClipFactory.asset(item))]}}static tracks(){return[["track_composition","Nested Sequences","composition"],["track_camera","Camera","camera"],["track_video","Real Video","video"],["track_titles","Titles + Bubbles","title"],["track_dialogue","Dialogue","dialogue"],["track_voice","Recorded Voice","audio"],["track_action","Character Action","action"],["track_emotion","Emotion","emotion"],["track_gesture","Gestures","gesture"],["track_props","Props","prop"],["track_effects","Effects","effect"],["track_music","Music + Foley","audio"]].map(([id,name,type])=>({id,name,type,locked:!1,muted:!1}))}static dialogueClips(dialogue){return dialogue.flatMap(line=>[MovieClipFactory.dialogue(line),MovieClipFactory.bubble(line)])}};export{MoviePlanCompiler};
